import { useState } from 'react';

// Dữ liệu đơn nghỉ phép mẫu
const initialLeaves = [
  { id: 1, name: 'Nguyễn Văn An', type: 'Nghỉ phép năm', from: '20/05/2026', to: '22/05/2026', days: 3, reason: 'Việc gia đình', status: 'Đã duyệt' },
  { id: 2, name: 'Trần Thị Bình', type: 'Nghỉ bệnh', from: '21/05/2026', to: '21/05/2026', days: 1, reason: 'Khám bệnh', status: 'Chờ duyệt' },
  { id: 3, name: 'Hoàng Văn Em', type: 'Nghỉ không lương', from: '25/05/2026', to: '27/05/2026', days: 3, reason: 'Du lịch cá nhân', status: 'Từ chối' },
  { id: 4, name: 'Phạm Thị Dung', type: 'Nghỉ phép năm', from: '01/06/2026', to: '03/06/2026', days: 3, reason: 'Nghỉ hè', status: 'Chờ duyệt' },
];

const statusStyle = {
  'Đã duyệt': { bg: '#dcfce7', color: '#16a34a' },
  'Chờ duyệt': { bg: '#fef9c3', color: '#a16207' },
  'Từ chối': { bg: '#fef2f2', color: '#dc2626' },
};

function LeaveRequests() {
  const [leaves] = useState(initialLeaves);

  return (
    <div>
      <h4 style={{ marginBottom: '4px', color: '#111' }}>Nghỉ phép</h4>
      <p style={{ color: '#888', fontSize: '14px', marginBottom: '20px' }}>
        Danh sách các đơn xin nghỉ phép của nhân viên.
      </p>

      <div style={{
        backgroundColor: '#fff',
        border: '1px solid #ddd',
        borderRadius: '8px',
        overflow: 'hidden'
      }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '14px' }}>
          <thead>
            <tr style={{ backgroundColor: '#f8f9fa', borderBottom: '1px solid #ddd' }}>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>STT</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Nhân viên</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Loại nghỉ</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Từ ngày</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Đến ngày</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Số ngày</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Lý do</th>
              <th style={{ padding: '12px 16px', textAlign: 'left', color: '#555' }}>Trạng thái</th>
            </tr>
          </thead>
          <tbody>
            {leaves.map((leave, index) => {
              const sc = statusStyle[leave.status] || { bg: '#f3f4f6', color: '#333' };
              return (
                <tr key={leave.id} style={{ borderBottom: '1px solid #f0f0f0' }}>
                  <td style={{ padding: '12px 16px', color: '#888' }}>{index + 1}</td>
                  <td style={{ padding: '12px 16px', color: '#222' }}>{leave.name}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{leave.type}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{leave.from}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{leave.to}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{leave.days}</td>
                  <td style={{ padding: '12px 16px', color: '#555' }}>{leave.reason}</td>
                  <td style={{ padding: '12px 16px' }}>
                    <span style={{
                      padding: '2px 8px',
                      borderRadius: '12px',
                      fontSize: '12px',
                      backgroundColor: sc.bg,
                      color: sc.color
                    }}>
                      {leave.status}
                    </span>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default LeaveRequests;
